// TREE NODE: the fundamental building block
class TreeNode {
    constructor(val, left = null, right = null) {
        this.val   = val;
        this.left  = left;
        this.right = right;
    }
}

// BUILD a tree manually for testing
//         4
//        / \
//       2   7
//      / \ / \
//     1  3 6  9
const root = new TreeNode(4,
    new TreeNode(2,
        new TreeNode(1),
        new TreeNode(3)
    ),
    new TreeNode(7,
        new TreeNode(6),
        new TreeNode(9)
    )
);

// TERMINOLOGY verification
function isLeaf(node) {
    return node !== null && node.left === null && node.right === null;
}

// HEIGHT: longest path from node down to any leaf
function height(node) {
    if (node === null) return -1;    // empty tree height is -1
    return 1 + Math.max(height(node.left), height(node.right));
}

// DEPTH: distance from root to a target node
function depth(root, target, d = 0) {
    if (root === null) return -1;    // not found
    if (root.val === target) return d;
    const leftDepth  = depth(root.left,  target, d + 1);
    const rightDepth = depth(root.right, target, d + 1);
    return leftDepth !== -1 ? leftDepth : rightDepth;
}

// COUNT NODES
function countNodes(node) {
    if (node === null) return 0;
    return 1 + countNodes(node.left) + countNodes(node.right);
}

console.log('Height of root:', height(root));           // 2
console.log('Height of node 2:', height(root.left));    // 1
console.log('Height of leaf 1:', height(root.left.left)); // 0
console.log('Depth of node 6:', depth(root, 6));        // 2
console.log('Is leaf 1?', isLeaf(root.left.left));      // true
console.log('Total nodes:', countNodes(root));           // 7

