// RECURSIVE DFS — three traversals, trivially short
function preorder(root, result = []) {
    if (!root) return result;
    result.push(root.val);            // process root FIRST
    preorder(root.left, result);
    preorder(root.right, result);
    return result;
}

function inorder(root, result = []) {
    if (!root) return result;
    inorder(root.left, result);
    result.push(root.val);            // process root BETWEEN children
    inorder(root.right, result);
    return result;
}

function postorder(root, result = []) {
    if (!root) return result;
    postorder(root.left, result);
    postorder(root.right, result);
    result.push(root.val);            // process root AFTER children
    return result;
}

// Tree:      4
//           / \
//          2   7
//         / \ / \
//        1  3 6  9
console.log(preorder(root));   // [4, 2, 1, 3, 7, 6, 9]  root-left-right
console.log(inorder(root));    // [1, 2, 3, 4, 6, 7, 9]  sorted (BST)
console.log(postorder(root));  // [1, 3, 2, 6, 9, 7, 4]  children before parent

// ITERATIVE PREORDER — explicit stack
function preorderIterative(root) {
    if (!root) return [];
    const result = [], stack = [root];
    while (stack.length) {
        const node = stack.pop();
        result.push(node.val);
        // Push right first so left is processed first (stack is LIFO)
        if (node.right) stack.push(node.right);
        if (node.left)  stack.push(node.left);
    }
    return result;
}

// ITERATIVE INORDER — explicit stack + curr pointer
function inorderIterative(root) {
    const result = [], stack = [];
    let curr = root;
    while (curr || stack.length) {
        // Go as far left as possible
        while (curr) { stack.push(curr); curr = curr.left; }
        // Process leftmost unprocessed node
        curr = stack.pop();
        result.push(curr.val);
        // Move to right subtree
        curr = curr.right;
    }
    return result;
}

