// BFS LEVEL ORDER — returns array of arrays, one per level
function levelOrder(root) {
    if (!root) return [];
    const result = [];
    const queue = [root];

    while (queue.length) {
        const levelSize = queue.length; // nodes at current level
        const level = [];

        for (let i = 0; i < levelSize; i++) {
            const node = queue.shift(); // dequeue front — O(n) naive!
            level.push(node.val);
            if (node.left)  queue.push(node.left);
            if (node.right) queue.push(node.right);
        }
        result.push(level);
    }
    return result;
}
// Tree: 4 / 2,7 / 1,3,6,9
// Result: [[4],[2,7],[1,3,6,9]]

// NOTE: queue.shift() is O(n). For large trees use a proper O(1) queue.
// In interviews, queue.shift() is acceptable for clarity.

// RIGHT SIDE VIEW — last node at each level
function rightSideView(root) {
    if (!root) return [];
    const result = [];
    const queue = [root];
    while (queue.length) {
        const levelSize = queue.length;
        for (let i = 0; i < levelSize; i++) {
            const node = queue.shift();
            if (i === levelSize - 1) result.push(node.val); // last in level
            if (node.left)  queue.push(node.left);
            if (node.right) queue.push(node.right);
        }
    }
    return result;
}
// Result for example tree: [4, 7, 9]

// ZIGZAG LEVEL ORDER — alternate direction per level
function zigzagLevelOrder(root) {
    if (!root) return [];
    const result = [];
    const queue = [root];
    let leftToRight = true;
    while (queue.length) {
        const levelSize = queue.length;
        const level = new Array(levelSize);
        for (let i = 0; i < levelSize; i++) {
            const node = queue.shift();
            const idx = leftToRight ? i : levelSize - 1 - i;
            level[idx] = node.val; // place at correct position
            if (node.left)  queue.push(node.left);
            if (node.right) queue.push(node.right);
        }
        result.push(level);
        leftToRight = !leftToRight;
    }
    return result;
}
// Result: [[4],[7,2],[1,3,6,9]]

