// MAXIMUM DEPTH (= height + 1 in LeetCode convention)
// LeetCode calls this 'maximum depth' = number of nodes on the path
function maxDepth(root) {
    if (!root) return 0;              // 0 nodes = depth 0
    return 1 + Math.max(maxDepth(root.left), maxDepth(root.right));
}
// Note: maxDepth(null)=0, maxDepth(leaf)=1, maxDepth(root of 3-level tree)=3
// This is height(root) + 1 using the height convention where height(null)=-1

// MINIMUM DEPTH — careful handling of one-child nodes
function minDepth(root) {
    if (!root) return 0;
    // Leaf node: both children null
    if (!root.left && !root.right) return 1;
    // Only right child: left subtree doesn't exist, can't be a path
    if (!root.left)  return 1 + minDepth(root.right);
    // Only left child: right subtree doesn't exist, can't be a path
    if (!root.right) return 1 + minDepth(root.left);
    // Both children exist: take minimum of both depths
    return 1 + Math.min(minDepth(root.left), minDepth(root.right));
}
// Without the one-child guards:
// minDepth would return 1 + min(0, depth(right)) = 1 for a node with only right child
// incorrectly treating the non-existent left path as depth 0

// DEPTH OF A SPECIFIC NODE (distance from root)
function nodeDepth(root, target, depth = 0) {
    if (!root) return -1;
    if (root.val === target) return depth;
    const left  = nodeDepth(root.left,  target, depth + 1);
    return left !== -1 ? left : nodeDepth(root.right, target, depth + 1);
}

// HEIGHT AS BUILDING BLOCK FOR BALANCE CHECK
function checkHeight(node) {
    // Returns actual height, or -2 as sentinel for 'unbalanced'
    if (!node) return -1;
    const leftH  = checkHeight(node.left);
    if (leftH === -2) return -2;  // short-circuit: already unbalanced
    const rightH = checkHeight(node.right);
    if (rightH === -2) return -2;
    if (Math.abs(leftH - rightH) > 1) return -2; // this node is unbalanced
    return 1 + Math.max(leftH, rightH);           // return actual height
}
console.log(checkHeight(root) !== -2); // true = balanced

