// NAIVE O(n^2) — recomputes height at every node
function diameterNaive(root) {
    if (!root) return 0;
    // Diameter through current root
    const leftH  = height(root.left)  + 1; // +1 for the edge to left child
    const rightH = height(root.right) + 1;
    const throughRoot = leftH + rightH;
    // Diameter NOT through current root
    const throughLeft  = diameterNaive(root.left);
    const throughRight = diameterNaive(root.right);
    return Math.max(throughRoot, throughLeft, throughRight);
}
// height() called separately at every node -> O(n) per node -> O(n^2) total

// OPTIMAL O(n) — compute height and update diameter in one pass
function diameterOfBinaryTree(root) {
    let maxDiameter = 0;

    function dfs(node) {
        if (!node) return -1; // height of null
        const leftH  = dfs(node.left);
        const rightH = dfs(node.right);
        // Diameter through this node: left subtree height + right subtree height + 2 edges
        // But using LeetCode edge-count convention:
        // leftH+1 = edges from this node to deepest left leaf
        // rightH+1 = edges from this node to deepest right leaf
        const diameter = (leftH + 1) + (rightH + 1);
        maxDiameter = Math.max(maxDiameter, diameter);
        // Return height of this subtree for the parent's computation
        return 1 + Math.max(leftH, rightH);
    }

    dfs(root);
    return maxDiameter;
}

