        const rightH = dfsHeight(node.right);
        if (rightH === -2) return -2;        // early exit: right unbalanced

        // Check balance at this node
        if (Math.abs(leftH - rightH) > 1) return -2; // this node unbalanced

        return 1 + Math.max(leftH, rightH); // balanced: return actual height
    }

    return dfsHeight(root) !== -2;
