    function dfs(node) {
        if (!node) return { height: -1, balanced: true };
        const left  = dfs(node.left);
        if (!left.balanced) return { height: 0, balanced: false }; // short-circuit
        const right = dfs(node.right);
        if (!right.balanced) return { height: 0, balanced: false };
        const balanced = Math.abs(left.height - right.height) <= 1;
        return { height: 1 + Math.max(left.height, right.height), balanced };
