function pathSumIII(root, targetSum) {
    // Prefix sum along current root-to-node path
    const prefixCounts = new Map([[0, 1]]); // sum 0 seen once (empty path)
    let count = 0;

    function dfs(node, currentSum) {
        if (!node) return;
        currentSum += node.val;
        // How many paths ending here have sum = targetSum?
        count += prefixCounts.get(currentSum - targetSum) || 0;
        // Add current sum to map
        prefixCounts.set(currentSum, (prefixCounts.get(currentSum) || 0) + 1);
        dfs(node.left,  currentSum);
        dfs(node.right, currentSum);
        // Backtrack: remove current sum from map when leaving this path
        prefixCounts.set(currentSum, prefixCounts.get(currentSum) - 1);
    }
    dfs(root, 0);
    return count;
}

