function searchBST(root, val) {
    if (!root) return null;             // not found
    if (root.val === val) return root;  // found
    if (val < root.val) return searchBST(root.left,  val); // go left
    return searchBST(root.right, val);                      // go right
}

// BST INSERT — O(h)
function insertIntoBST(root, val) {
    if (!root) return new TreeNode(val); // base: insert here
    if (val < root.val) {
        root.left  = insertIntoBST(root.left,  val); // recurse left
    } else {
        root.right = insertIntoBST(root.right, val); // recurse right
    }
    return root; // return root unchanged for linking
}

// BST DELETE — O(h), three cases
function deleteNode(root, key) {
    if (!root) return null;
    if (key < root.val) {
        root.left  = deleteNode(root.left,  key);
    } else if (key > root.val) {
        root.right = deleteNode(root.right, key);
    } else {
        // Found node to delete
        if (!root.left)  return root.right; // case 1&2: no left child
        if (!root.right) return root.left;  // case 2: no right child
        // Case 3: two children — find in-order successor (min of right subtree)
        let successor = root.right;
        while (successor.left) successor = successor.left;
        root.val   = successor.val;                          // replace value
        root.right = deleteNode(root.right, successor.val); // delete successor
    }
    return root;
}

